head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.fn_close = function(arg) {
    window.al = "test ==>" + arg;
    console.log("test ==>" + arg);
    return true;
}
scwin.trigger1_onclick = function(e) {
    //windowContainer1_subWindow0_close
    windowContainer1.createWindow("test1", null, "", "test1", "id1", "newWindow", "scwin.fn_close");
};
scwin.trigger2_onclick = function(e) {
    ///temp/jsonToXml.xml
    windowContainer1.createWindow("test2", null, "", "test2", "id1", "newWindow", "scwin.fn_close");
};
scwin.__isShowConsole = function(val) {
    return window.al == val;
}
scwin.__isShow = function(id) {
    var el = scwin.__getDom($p.id + id);
    return (el) ? true : false;
}
scwin.__triggerClick = function(id) {
    return scwin.__getDom($p.id + id).click();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //windowContainer1.createWindow( "test" , null , "/temp/jsonToXml.xml" , "test" , "id1" , "existWindow" , "fn_close" );
    window.al = undefined;
}
